local shape_chunks = {}
for i = 1, 4 do
  shape_chunks[i] = MODULE .. string.format(".shapes_%03d", i)
end

local where -- shape name -> file number, built on the first lookup

-- The registry: a lookup of a shape not loaded yet loads its whole file. An unknown name is nil. A
-- missing file raises, as a missing module does.
local shapes = setmetatable({}, {
  __index = function(registry, name)
    if where == nil then
      where = {}
      for file, shape in string.gmatch(SHAPES, "(%d+) ([^\n]+)") do
        where[shape] = file
      end
      SHAPES = nil
    end
    local file = where[name]
    if file == nil then
      return nil
    end
    for k, node in pairs(require(MODULE .. ".shapes_" .. file)) do
      rawset(registry, k, node)
    end
    return rawget(registry, name)
  end,
})

local classes = {}

local ops = {}
for i = 1, 1 do
  for name, op in pairs(require(MODULE .. string.format(".ops_%03d", i))) do
    ops[name] = op
  end
end

return {
  name = "azure.managednetworkfabric",
  shapes = shapes,
  errors = classes,
  ops = ops,
  shape_chunks = shape_chunks,
  telemetry = {
    system = "azure-api",
    prefix = "Managednetworkfabric",
    service = "Managednetworkfabric",
    labels = "azure",
    label_names = {
      l2IsolationDomainName = "azure.l2_isolation_domain_name",
      l3IsolationDomainName = "azure.l3_isolation_domain_name",
      resourceGroupName = "azure.resource_group.name",
    },
    attributes = { ["azure.resource_provider.namespace"] = "Microsoft.ManagedNetworkFabric" },
    propagate = "w3c",
    response_headers = {
      { header = "x-request-id", name = "http.response.header.x-request-id", transform = "list" },
      { header = "request-id", name = "http.response.header.request-id", transform = "list" },
      {
        header = "x-ms-correlation-request-id",
        name = "http.response.header.x-ms-correlation-request-id",
        transform = "list",
      },
      { header = "x-ms-request-id", name = "azure.service.request.id" },
    },
  },
}
